import {estimate} from './model.js';
const $ = id => document.getElementById(id);
const nf = new Intl.NumberFormat('en-US',{maximumFractionDigits:0});
const monthName = value => new Date(value.slice(0,7)+'-15T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'});
const shortMonth = value => new Date(value.slice(0,7)+'-15T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});
const mint='#69e7c0',blue='#82b6ff',orange='#efa87c',muted='#9bb1c4';
let data,current,page='estimate',mapReady=false;
const config={responsive:true,displaylogo:false,displayModeBar:false,scrollZoom:false,topojsonURL:new URL('./assets/',location.href).href};
const layout={paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{family:'Arial, sans-serif',color:muted,size:11},margin:{t:18,b:52,l:60,r:18},xaxis:{gridcolor:'#29384a',zeroline:false},yaxis:{gridcolor:'#29384a',zeroline:false},legend:{orientation:'h',y:-.25,x:0,font:{size:10}},hoverlabel:{bgcolor:'#203449',font:{color:'#edf4fb'}},autosize:true};
function chart(id,traces,overrides={}){return Plotly.react($(id),traces,structuredClone({...layout,...overrides}),{...config})}
const descriptions={1:'A manufactured or mobile home designed to be transported and placed on a site.',2:'A single-family house with no shared walls with another home.',3:'A single-family home that shares at least one wall with another home, such as a townhouse.',4:'Your own apartment in a building containing 2–4 apartments. This count describes the building, not your bedrooms.',5:'Your own apartment in a building containing 5 or more apartments—including tall buildings with 50 or 100+ units. This survey category does not distinguish their exact building size.'};
function stateOptions(el){Object.entries(data.states).sort((a,b)=>a[1].name.localeCompare(b[1].name)).forEach(([code,state])=>el.add(new Option(state.name,code)));el.value='MA'}
async function renderMap(){const state=$('state').value,codes=Object.keys(data.states).sort();await chart('state-map',[
 {type:'choropleth',locations:codes,locationmode:'USA-states',z:codes.map(x=>+(x===state)),zmin:0,zmax:1,colorscale:[[0,'#294459'],[1,mint]],showscale:false,marker:{line:{color:'#7190a4',width:.7}},customdata:codes.map(x=>data.states[x].name),hovertemplate:'<b>%{customdata}</b><br>Click to select<extra></extra>'},
 {type:'scattergeo',lon:[-77.0369],lat:[38.9072],mode:'markers+text',text:['DC'],textposition:'bottom right',textfont:{color:'#d8e6f0',size:10},customdata:['DC'],marker:{size:9,color:state==='DC'?mint:blue,line:{color:'#0b111b',width:1}},hovertemplate:'Washington, D.C.<br>Click to select<extra></extra>',showlegend:false}
 ],{margin:{t:0,b:0,l:0,r:0},geo:{scope:'usa',projection:{type:'albers usa'},bgcolor:'transparent',showland:true,landcolor:'#182b3b',showlakes:false,showcoastlines:false,showcountries:false,showsubunits:false},dragmode:false,uirevision:'homepulse-map',showlegend:false});
 if(!mapReady){$('state-map').on('plotly_click',event=>{const point=event.points[0];const selected=point.location||(point.customdata==='DC'?'DC':null);if(data.states[selected]){$('state').value=selected;update();renderMap()}});mapReady=true;}}
function renderOutlook(state){const h=data.history.filter(x=>x.state===state),f=data.forecasts.filter(x=>x.state===state);$('trend-title').textContent=data.states[state].name+' · electricity outlook';chart('outlook-chart',[
 {x:h.map(x=>x.date),y:h.map(x=>x.sales_mwh),type:'scatter',mode:'lines',name:'EIA recorded',line:{color:blue,width:2.5}},
 {x:f.map(x=>x.month+'-01'),y:f.map(x=>x.xgboost_mwh),type:'scatter',mode:'lines+markers',name:'Forecast',line:{color:mint,width:2.5,dash:'dash'}}
 ],{hovermode:'x unified',yaxis:{...layout.yaxis,title:{text:'Residential sales (MWh)',font:{size:10}},tickformat:'~s'}})}
function update(){const state=$('state').value,kind=Number($('home-type').value),area=Number($('area').value),month=$('month').value;
 $('home-help').textContent=descriptions[kind];$('state-chip').textContent=state;$('area-metric').textContent=Number.isFinite(area)&&area>0?'≈ '+nf.format(area*.092903)+' m²':'';
 $('result-month').textContent=shortMonth(month);$('result-location').textContent=data.states[state].name;$('result-profile').textContent=data.home_types[kind]+' · '+nf.format(area)+' sq ft';
 $('form-error').hidden=true;$('area').removeAttribute('aria-invalid');renderOutlook(state);
 try{current=estimate(data,state,month,kind,area);$('result-kwh').textContent=nf.format(current.estimate_kwh);$('download').disabled=false;
 const diff=(current.factor-1)*100;$('result-context').textContent=Math.abs(diff).toFixed(0)+'% '+(diff>=0?'above':'below')+' the forecast state account average for this month.';
 chart('comparison-chart',[{type:'bar',x:[current.account_kwh,current.estimate_kwh],y:['State average','Home profile'],orientation:'h',text:[nf.format(current.account_kwh),nf.format(current.estimate_kwh)],textposition:'outside',cliponaxis:false,marker:{color:[blue,mint]},hovertemplate:'%{y}<br>%{x:,.0f} kWh<extra></extra>'}],{margin:{l:104,r:42,t:10,b:42},xaxis:{...layout.xaxis,type:'linear',title:{text:'Estimated monthly kWh',font:{size:10}},tickangle:0,nticks:3,rangemode:'tozero'},yaxis:{type:'category',autorange:'reversed',tickfont:{size:11}},showlegend:false,bargap:.52});
 $('support-n').textContent=nf.format(current.sample_n);$('support-geo').textContent=current.geography;$('support-level').textContent=current.level+' comparison group';$('support-detail').textContent='Matching home type and size band: '+current.size_band+'. '+(current.level==='State'?'This state has sufficient survey support.':'The state group was too small; a broader geographic group is used.')+' Survey weights are applied.';
 }catch(error){current=null;$('form-error').textContent=error.message;$('form-error').hidden=false;$('result-kwh').textContent='—';$('result-context').textContent='An estimate is unavailable for this profile.';$('download').disabled=true;$('support-n').textContent='—';$('support-geo').textContent='Unavailable';$('support-detail').textContent=error.message;$('support-level').textContent='No estimate calculated';Plotly.purge($('comparison-chart'));if(!Number.isFinite(area)||area<200||area>15000)$('area').setAttribute('aria-invalid','true');}}
function go(next){if(!['estimate','method'].includes(next))next='estimate';page=next;document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!=='page-'+next);document.querySelectorAll('.nav').forEach(x=>{x.classList.toggle('active',x.dataset.page===next);if(x.dataset.page===next)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});history.replaceState(null,'','#'+next);if(next==='estimate'){update();renderMap()}requestAnimationFrame(()=>{document.querySelectorAll('.page:not([hidden]) .js-plotly-plot').forEach(el=>Plotly.Plots.resize(el))})}
function download(){if(!current)return;const report={project:'HomePulse',description:'Unvalidated monthly household planning scenario, not a utility bill',state_name:data.states[current.state].name,home_type:data.home_types[current.kind],...current,snapshot_date:data.snapshot_date,sources:[data.metadata.eia_url,data.metadata.recs_url]};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.href=url;a.download=`HomePulse-${current.state}-${current.month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('toast').textContent='Estimate report downloaded';$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3000)}
try{const response=await fetch('assets/homepulse-data.json');if(!response.ok)throw new Error('Data snapshot could not be loaded.');data=await response.json();stateOptions($('state'));data.metadata.estimate_months.forEach(x=>$('month').add(new Option(monthName(x),x)));$('month').value='2026-11';
 document.querySelectorAll('.nav').forEach(x=>x.addEventListener('click',()=>go(x.dataset.page)));document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('estimate')});$('estimate-button').addEventListener('click',()=>{update();if(current&&innerWidth<701)document.querySelector('.result')?.scrollIntoView({behavior:'smooth'})});
 $('state').addEventListener('change',()=>{update();renderMap()});['month','home-type','area'].forEach(id=>$(id).addEventListener('change',update));$('area').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();update()}});$('download').addEventListener('click',download);$('loading').hidden=true;go(location.hash.slice(1)||'estimate');
}catch(error){$('loading').hidden=true;$('fatal').textContent='HomePulse could not load. Please refresh the page. '+error.message;$('fatal').hidden=false;console.error(error)}
